#!/usr/bin/env bash
set -euo pipefail
mkdir -p claude-mobile-studio-build
cat <<'CLAUDE_MOBILE_STUDIO_V03' | base64 -d | tar -xJ -C claude-mobile-studio-build

CLAUDE_MOBILE_STUDIO_V03
python3 - <<'PY'
from pathlib import Path
p=Path('claude-mobile-studio-build/app/src/main/java/com/claudemobilestudio/app/MainActivity.java')
s=p.read_text()
s=s.replace('com 900 KB cada.\nArquivos como APK','com 900 KB cada.\\nArquivos como APK')
p.write_text(s)
PY
cd claude-mobile-studio-build
gradle --no-daemon :app:assembleDebug
